import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [userId, setUserId] = useState("");
  const [qrData, setQrData] = useState("");
  const [photo, setPhoto] = useState("");

  const [paid, setPaid] = useState(false);
  const [loadingPayment, setLoadingPayment] = useState(false);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* ================= FACE MODEL ================= */
  useEffect(() => {
    const loadModels = async () => {
      const MODEL_URL = "/models";
      await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
    };
    loadModels();
  }, []);

  /* ================= FORM ================= */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* ================= PAYMENT (IMPROVED) ================= */
  const handlePayment = async (e) => {
    e.preventDefault();

    setLoadingPayment(true);

    // Simulate payment delay (like Razorpay / UPI)
    setTimeout(async () => {
      setLoadingPayment(false);
      setPaid(true);
      alert("✅ Payment Successful");

      // Auto register after payment
      await registerUser();
    }, 2000);
  };

  /* ================= REGISTER ================= */
  const registerUser = async () => {
    try {
      const res = await axios.post("http://localhost:5000/register", {
        ...formData,
        photo,
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
      } else {
        alert(res.data.message);
      }
    } catch {
      alert("Registration Failed");
    }
  };

  /* ================= CAMERA ================= */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch {
      alert("Camera access denied");
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;

    const detections = await faceapi.detectAllFaces(
      video,
      new faceapi.TinyFaceDetectorOptions()
    );

    if (detections.length === 0) return alert("No face detected ❌");
    if (detections.length > 1) return alert("Only one person allowed ❌");

    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, 0, 0);

    const image = canvas.toDataURL("image/png");
    setPhoto(image);

    // Stop camera
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
    }
  };

  /* ================= DOWNLOAD ================= */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "Event_ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  /* ================= UI ================= */
  const pageStyle = {
    minHeight: "100vh",
    background: "linear-gradient(135deg, #141e30, #243b55)",
    color: "white",
  };

  const containerStyle = {
    textAlign: "center",
    padding: "30px",
  };

  const cardStyle = {
    backdropFilter: "blur(15px)",
    background: "rgba(255,255,255,0.08)",
    padding: "20px",
    borderRadius: "15px",
    width: "320px",
    margin: "auto",
    display: "flex",
    flexDirection: "column",
    gap: "12px",
  };

  const inputStyle = {
    padding: "10px",
    borderRadius: "8px",
    border: "none",
    background: "rgba(255,255,255,0.2)",
    color: "white",
  };

  const buttonStyle = {
    padding: "10px",
    borderRadius: "20px",
    border: "none",
    cursor: "pointer",
    background: "linear-gradient(135deg, #ff7eb3, #ff758c)",
    color: "white",
    fontWeight: "bold",
  };

  const videoStyle = {
    width: "100%",
    borderRadius: "10px",
  };

  const idCardStyle = {
    background: "white",
    color: "black",
    padding: "15px",
    borderRadius: "12px",
    width: "250px",
    margin: "auto",
    textAlign: "center",
  };

  const imageStyle = {
    width: "100px",
    borderRadius: "8px",
    marginTop: "10px",
  };

  return (
    <div style={pageStyle}>
      <Navbar />

      <div style={containerStyle}>
        <h2>✨ Event Registration</h2>

        {!qrData && (
          <form style={cardStyle} onSubmit={handlePayment}>
            <input style={inputStyle} name="name" placeholder="Name" onChange={handleChange} required />
            <input style={inputStyle} name="college_name" placeholder="College Name" onChange={handleChange} required />
            <input style={inputStyle} name="phone" placeholder="Phone" onChange={handleChange} required />
            <input style={inputStyle} name="email" placeholder="Email" onChange={handleChange} required />

            <h3>🎯 {eventName}</h3>

            <button style={buttonStyle} type="submit">
              {loadingPayment ? "Processing Payment..." : "Pay Now"}
            </button>
          </form>
        )}

        {qrData && (
          <div style={cardStyle}>
            <h3>Your QR Code</h3>
            <QRCode value={qrData.toString()} size={180} />

            <button style={buttonStyle} onClick={openCamera}>Open Camera</button>

            <video ref={videoRef} style={videoStyle} />

            <button style={buttonStyle} onClick={capturePhoto}>Capture Photo</button>

            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {photo && (
          <div style={{ marginTop: "30px" }}>
            <div ref={idCardRef} style={idCardStyle}>
              <h3>🎫 Event ID</h3>
              <p>{formData.name}</p>
              <p>ID: {userId}</p>
              <p>{eventName}</p>

              <QRCode value={qrData.toString()} size={100} />
              <img src={photo} alt="User" style={imageStyle} />
            </div>

            <button style={{ ...buttonStyle, marginTop: "15px" }} onClick={downloadCard}>
              Download ID Card
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
